    /**
     * Tests getting all LoanPayments.
     *
     * @return    Collection
     */
    public List<LoanPayment> testGetAll() throws Throwable {
    LOGGER.info( "LoanPaymentTest:testGetAll() - Retrieving Collection of LoanPayments:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all LoanPayment : " );
    List<LoanPayment> collection  = null;

    try {
        // call the static get method on the LoanPaymentService
        collection = service.getAllLoanPayment();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            LoanPayment currEntity  = null;
            Iterator<LoanPayment> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getLoanPaymentId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

